import "core-js/modules/es.array.push.js";
import { list_expense_category } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "@/components/SnackBar.vue";
// import AddExpenseconfi from "./ExpensePopups/AddExpenseconfi.vue";
import DeleteExpenseconfi from "./ExpensePopups/DeleteExpenseconfi.vue";
export default {
  components: {
    SnackBar,
    // AddExpenseconfi,
    DeleteExpenseconfi
  },
  data() {
    return {
      fixed: true,
      tableData: [],
      SnackBarComponent: {},
      tableLoading: false,
      addConfiguration: false,
      deleteExpense: false,
      height: 0,
      headers: [{
        title: "Category",
        value: "expense_name",
        sortable: false
      }, {
        title: "Created By",
        value: "expense_created_by",
        sortable: false
      }, {
        title: "Actions",
        value: "actions",
        sortable: false
      }

      // {
      //   text: "Role",
      //   value: "user_type",
      //   sortable: false,
      // },
      // {
      //   text: "Action",
      //   value: "action",
      //   sortable: false,
      // },
      ],
      componentCheck: 0,
      custom_details: {},
      currentPage: 1,
      itemsPerPage: 10
    };
  },
  computed: {
    totalItems() {
      return this.tableData.length;
    },
    pageCount() {
      return Math.ceil(this.totalItems / this.itemsPerPage);
    },
    sortedAndPaginatedItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.tableData.slice(start, end);
    },
    visiblePages() {
      const pages = [];
      const start = Math.max(1, this.currentPage - 2);
      const end = Math.min(this.pageCount, this.currentPage + 2);
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  created() {
    this.height = window.innerHeight - 250;
    this.fetch_expenses();
  },
  methods: {
    add_expense() {
      this.componentCheck = 1;
      this.addConfiguration = true;
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    delete_item(item) {
      this.componentCheck = 2;
      this.custom_details = item;
      this.deleteExpense = true;
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.addConfiguration = false;
      this.deleteExpense = false;
      this.fetch_expenses();
    },
    handleSortChange() {
      // Implement sorting logic if needed
    },
    async fetch_expenses() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_expense_category, {
          input: {
            organization_id: data.organization.organization_id,
            nextToken: null,
            limit: 100
          }
        }));
        this.tableLoading = false;
        this.tableData = [];
        var response = JSON.parse(result.data.list_expense_category);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.tableData = response.data;
        } else {
          // this.SnackBarComponent = {
          //   SnackbarVmodel: true,
          //   SnackbarColor: "red",
          //   SnackbarText: response.Message,
          //   timeout: 5000,
          //   Top: true,
          // };
        }
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    }
  }
};
